// A key's name (8 characters) for the controls card; code 0x1FE = CLICK
module osk_key_name (
	input  wire [8:0] code,
	input  wire [2:0] pos,
	output wire [6:0] glyph
);
reg [55:0] name;
always @(*) begin
	case (code)
	9'h000: name = 56'h00000000000026;   // -
	9'h00D: name = 56'h00000000008094;   // TAB
	9'h00E: name = 56'h00000000000025;   // `
	9'h00F: name = 56'h00000004E0080B;   // KP =
	9'h011: name = 56'h000000000022C4;   // {APPLE}
